/**
 * The differential sweep's two tables.
 *
 * 5586 inputs: every prefix the design derives from the two machines'
 * behavior, each followed by every ASCII character and a `1`, plus the mixed
 * two-character boundaries that a single-character sweep cannot see.
 *
 * `expected` is what this module's own tokenizer produces, and is what
 * [`proof.f.mjs`](./proof.f.mjs) asserts against. `recorded` is what the
 * wrapper over `fjs/js/tokenizer` produced before the port, captured once so a
 * reviewer can diff the two; nothing imports `fjs/js/tokenizer` to obtain it,
 * which is what lets stage 7 delete that machine without rewriting this proof.
 *
 * Rows are `[input, tokens]`, the tokens rendered as a single line —
 * `E(message)` for an error, `kind(value)` for a token that carries one.
 *
 * Generated. Do not edit by hand.
 *
 * @module
 */

